-- ============================================================================
-- SINAGERSAT - Migración v2.13.0 (idempotente)
-- Catálogo canónico edan.tipo_evento (48 tipos):
--   * Amplía `descripcion` a TEXT (hoy VARCHAR(150), hay descripciones de 436 chars).
--   * Agrega columnas `grupo` y `categoria` (fuente: hoja `eventos` del Excel legacy).
--   * Renombra en el lugar los eventos equivalentes (preserva ids y referencias).
--   * Elimina filas de categoría sin referencias (10, 11, 15, 16, 17, 18).
--   * Inserta los 32 eventos faltantes y ajusta la secuencia.
-- NO afecta las APIs: los GET consultan columnas fijas o SELECT * y los schemas
-- solo exponen id_tipo_evento/nombre/descripcion.
-- ============================================================================

BEGIN;

ALTER TABLE edan.tipo_evento ALTER COLUMN descripcion TYPE TEXT;

ALTER TABLE edan.tipo_evento
    ADD COLUMN IF NOT EXISTS grupo VARCHAR(60),
    ADD COLUMN IF NOT EXISTS categoria VARCHAR(60);

COMMENT ON COLUMN edan.tipo_evento.grupo IS 'Grupo del evento (Meteorológico, Hidrológico, Geológico, Biológico, Antrópico y tecnológico, Otro).';
COMMENT ON COLUMN edan.tipo_evento.categoria IS 'Categoría del evento (ej: Tormenta, Inundación, Erupción volcánica).';

-- Renombre y backfill de las filas existentes (ids estables)
UPDATE edan.tipo_evento SET nombre = 'Inundaciones ocasionales', grupo = 'Hidrológico', categoria = 'Inundación', descripcion = 'Son inudaciones que ocurren debido a precipitación intensa y/o desborde de ríos, causados por lluvias continuas, ocurren en llanuras aluviales de ríos, la duración del estancamiento de las aguas puede variar de 1 a 30 días. ' WHERE id_tipo_evento = 1;
UPDATE edan.tipo_evento SET nombre = 'Riadas', grupo = 'Hidrológico', categoria = 'Inundación', descripcion = 'Afluencia repentina y violenta del agua de un río en pendientes moderadas a altas, producidas por precipitación intensa en las partes altas de la cuenca.' WHERE id_tipo_evento = 2;
UPDATE edan.tipo_evento SET nombre = 'Deslizamientos', grupo = 'Geológico', categoria = 'Movimiento de masas', descripcion = 'Es un movimiento de masa de tierra provocado por la inestabilidad de un talud.' WHERE id_tipo_evento = 3;
UPDATE edan.tipo_evento SET nombre = 'Heladas', grupo = 'Meteorológico', categoria = 'Heladas', descripcion = 'Descenso extremo de la temperatura mínima en la superficie del suelo.' WHERE id_tipo_evento = 4;
UPDATE edan.tipo_evento SET nombre = 'Granizadas', grupo = 'Meteorológico', categoria = 'Granizadas', descripcion = 'Gotas de agua que se congelan  en la parte superior de las nubes y caen a la superficie terrestre sin derretirse.' WHERE id_tipo_evento = 5;
UPDATE edan.tipo_evento SET nombre = 'Sequía meteorológica', grupo = 'Cambio climático', categoria = 'Sequía', descripcion = 'Situación climatológica anormal que se da por la falta de precipitación (lluvia) en una zona, durante un período de tiempo prolongado de tiempo.' WHERE id_tipo_evento = 6;
UPDATE edan.tipo_evento SET nombre = 'Incendios forestales', grupo = 'Antrópico y tecnológico', categoria = 'Incendios', descripcion = 'Fuego no controlado,  que afecta a bosques y superficies con cobertura vegetal, por causa natural o inducida que puede causar daño a las personas, bienes o medio ambiente.' WHERE id_tipo_evento = 7;
UPDATE edan.tipo_evento SET nombre = 'Tormenta eléctrica', grupo = 'Meteorológico', categoria = 'Tormenta', descripcion = 'Descarga brusca de electricidad atmosférica (relámpago, rayo, trueno) dentro de una nube, entre nubes y nube un determinado tiempo, y suelen acompañrase de chubasco, lluvia o granizo' WHERE id_tipo_evento = 8;
UPDATE edan.tipo_evento SET nombre = 'Nevadas', grupo = 'Meteorológico', categoria = 'Nevadas', descripcion = 'Precipitación sólida en forma de copos de diferentes formas y tamaños, habituales en el periodo invernal.' WHERE id_tipo_evento = 12;
UPDATE edan.tipo_evento SET nombre = 'Derretimiento de glaciares', grupo = 'Cambio climático', categoria = 'Derretimiento de glaciares', descripcion = 'Cambio de estado físico de solido a líquido por efecto del calentamiento global de masas o estructuras de hielo muy compactas que se acumuló en ciertas área de la cordillera.' WHERE id_tipo_evento = 13;
UPDATE edan.tipo_evento SET nombre = 'Terremoto/Sismo/Temblor', grupo = 'Geológico', categoria = 'Terremotos', descripcion = 'Son movimientos bruscos y repentinos de corta duración en la corteza terrestre producidos por la liberación de energía.' WHERE id_tipo_evento = 14;
UPDATE edan.tipo_evento SET nombre = 'Explosiones', grupo = 'Antrópico y tecnológico', categoria = 'Explosiones', descripcion = 'Liberación violenta de una cierta dosis de energía que estaba atrapada en un espacio reducido, generando un repentino aumento de la presión y haciendo que se desprenda luminosidad, gas y calor.' WHERE id_tipo_evento = 19;
UPDATE edan.tipo_evento SET nombre = 'Conflictos sociales', grupo = 'Antrópico y tecnológico', categoria = 'Disturbios sociales', descripcion = 'Es un proceso complejo en el cual la sociedad organizada, percibe que sus posiciones e intereses, objetivos, valores, creencias o necesidades son diferentes, al sector público o privado, creando una inestabilidad social que puede derivar en violencia.' WHERE id_tipo_evento = 20;
UPDATE edan.tipo_evento SET nombre = 'Transporte', grupo = 'Antrópico y tecnológico', categoria = 'Accidentes', descripcion = 'Es todo suceso imprevisto que afecta negativamente a una persona o grupo, alterando  la normalidad de la vida y los bienes, esos sucesos involucran a medios de tipo aéreo, naval, ferroviario y terrestre.' WHERE id_tipo_evento = 21;
UPDATE edan.tipo_evento SET nombre = 'Colapso estructural', grupo = 'Antrópico y tecnológico', categoria = 'Fallas estructurales', descripcion = 'Es la disminución de resistencia por cualquier condición externa o interna que incapacita a una estructura o elemento estructural a cumplir la función para la que ha sido deseñada, las causas pueden ser por ciertos factores, estos son: mal diseño, construcción defectuosa, fallas en cimientos, cargas extraordinarias, fallas inesperadas o combinación de estos que pueden afectar a cualquier estructura construida por la mano del hombre.' WHERE id_tipo_evento = 22;
UPDATE edan.tipo_evento SET nombre = 'Radiación', grupo = 'Antrópico y tecnológico', categoria = 'Radiación', descripcion = 'Es la energía en movimiento que es emitida, propagada y transferida por cualquie medio en forma de electromagnéticas o partículas subatómicas que se realiza a través del vacío o de un medio material, existen diversos tipos de radiación de las cuales podemos mencionar: Electromagnética, Ionizante, Corpuscular y Solar.' WHERE id_tipo_evento = 23;

-- Eliminación de filas de categoría sin referencias (guardada por nombre antiguo
-- para ser idempotente: en re-ejecuciones esos ids ya pertenecen al catálogo canónico)
DELETE FROM edan.tipo_evento
WHERE id_tipo_evento IN (10, 11, 15, 16, 17, 18)
  AND nombre IN ('Temperaturas extremas', 'Temporales de viento', 'Erupcion volcanica',
                 'Plagas', 'Contaminación', 'Degradación');

-- Inserciones de los eventos faltantes (ids estables)
INSERT INTO edan.tipo_evento (id_tipo_evento, nombre, descripcion, grupo, categoria) VALUES (9, 'Tormenta de arena', 'Vientos de sufieciente intensidad que soplan sobre arena suelta en una superficie seca. Las partículas de arena son de esta forma transportadas en la dirección del viento.', 'Meteorológico', 'Tormenta') ON CONFLICT (nombre) DO NOTHING;
INSERT INTO edan.tipo_evento (id_tipo_evento, nombre, descripcion, grupo, categoria) VALUES (10, 'Olas de frío', 'Temperaturas del aire que experimenta una disminución considerable en relación a sus temperaturas mínimas normales de la región, que se prolonga por 3 día o más.', 'Meteorológico', 'Temperaturas extremas') ON CONFLICT (nombre) DO NOTHING;
INSERT INTO edan.tipo_evento (id_tipo_evento, nombre, descripcion, grupo, categoria) VALUES (11, 'Olas de calor', 'Temperatura del aire que experimenta un incremento considerable en relación a sus termperaturas máximas normales de la región, que se prolonga por 3 días o más.', 'Meteorológico', 'Temperaturas extremas') ON CONFLICT (nombre) DO NOTHING;
INSERT INTO edan.tipo_evento (id_tipo_evento, nombre, descripcion, grupo, categoria) VALUES (15, 'Vientos fuertes', 'Corrientes de aire de gran intensidad y con velocidades mucho más altas que lo normal.', 'Meteorológico', 'Temporales de viento') ON CONFLICT (nombre) DO NOTHING;
INSERT INTO edan.tipo_evento (id_tipo_evento, nombre, descripcion, grupo, categoria) VALUES (16, 'Tornados', 'Remolino de viento de altas velocidades con forma de embudo, se extienden a partir de una enorme y densa nube y llegan hasta el suelo.', 'Meteorológico', 'Temporales de viento') ON CONFLICT (nombre) DO NOTHING;
INSERT INTO edan.tipo_evento (id_tipo_evento, nombre, descripcion, grupo, categoria) VALUES (17, 'Lluvias intensas', 'Son precipitaciones de gran magnitud y corta duración que, al superar la capacidad de absorción del suelo y de los sistemas de drenaje, se convierten en un evento dañino.', 'Meteorológico', 'Lluvias intensas') ON CONFLICT (nombre) DO NOTHING;
INSERT INTO edan.tipo_evento (id_tipo_evento, nombre, descripcion, grupo, categoria) VALUES (18, 'Sequía agrícola', 'Insuficiente humedad en el suelo para garantizar el desarrollo de una cultivo en cualquiera de sus fases de crecimiento.', 'Cambio climático', 'Sequía') ON CONFLICT (nombre) DO NOTHING;
INSERT INTO edan.tipo_evento (id_tipo_evento, nombre, descripcion, grupo, categoria) VALUES (24, 'Sequía hidrológica', 'Periodo de tiempo en el cual los recursos hídricos (Ríos, lagos, aguas subterráneas,  embalses, etc.) son insuficientes para satisfacer los usos establecidos.', 'Cambio climático', 'Sequía') ON CONFLICT (nombre) DO NOTHING;
INSERT INTO edan.tipo_evento (id_tipo_evento, nombre, descripcion, grupo, categoria) VALUES (25, 'Sequía socioeconómica', 'Escasez de agua inusual que genera impactos adversos en la sociedad o sus medios de vida,  produciendo daños en un determinado lugar.', 'Cambio climático', 'Sequía') ON CONFLICT (nombre) DO NOTHING;
INSERT INTO edan.tipo_evento (id_tipo_evento, nombre, descripcion, grupo, categoria) VALUES (26, 'Anegamiento', 'Son inundaciones que ocurren dentro de las primeras seis horas de lluvia intensa, sobre todo en áreas urbanas o rrurales y que permanece por un periodo de tiempo de más de 72 horas.', 'Hidrológico', 'Inundación') ON CONFLICT (nombre) DO NOTHING;
INSERT INTO edan.tipo_evento (id_tipo_evento, nombre, descripcion, grupo, categoria) VALUES (27, 'Inundaciones estacionales prolongadas', 'Ocupación lenta de agua por precipitación intensa que permanece por un periodo de tiempo superior a 60 días, en llanuras o áreas con relieve plano.', 'Hidrológico', 'Inundación') ON CONFLICT (nombre) DO NOTHING;
INSERT INTO edan.tipo_evento (id_tipo_evento, nombre, descripcion, grupo, categoria) VALUES (28, 'Turbión', 'Crecida del nivel de las aguas en ríos de llanura con pendientes baja, arrastrando en su curso sedimentos y empalizadas con una velocidad moderada a fuerte.', 'Hidrológico', 'Inundación') ON CONFLICT (nombre) DO NOTHING;
INSERT INTO edan.tipo_evento (id_tipo_evento, nombre, descripcion, grupo, categoria) VALUES (29, 'Desbordes', 'Rebalse del curso natural de un río o afluentes de agua producto de una crecida extraordinaria del nivel del agua sobrepasando el nivel del barranco.', 'Hidrológico', 'Inundación') ON CONFLICT (nombre) DO NOTHING;
INSERT INTO edan.tipo_evento (id_tipo_evento, nombre, descripcion, grupo, categoria) VALUES (30, 'Flujos de lodo', 'El deslizamiento es la mezcla de tierra, agua y vegetación formando un lodo el cual se desplaza y produce alteraciones en los medios de vida.', 'Geológico', 'Movimiento de masas') ON CONFLICT (nombre) DO NOTHING;
INSERT INTO edan.tipo_evento (id_tipo_evento, nombre, descripcion, grupo, categoria) VALUES (31, 'Hundimiento de suelos', 'Pérdida de estabilidad geológica que afecta la superficie de la tierra.', 'Geológico', 'Movimiento de masas') ON CONFLICT (nombre) DO NOTHING;
INSERT INTO edan.tipo_evento (id_tipo_evento, nombre, descripcion, grupo, categoria) VALUES (32, 'Derrumbes', 'Caída de tierra  o materiales de alturas elevadad, mayormente son rápidas, esto es ocasionado por el hombre o por la naturaleza.', 'Geológico', 'Movimiento de masas') ON CONFLICT (nombre) DO NOTHING;
INSERT INTO edan.tipo_evento (id_tipo_evento, nombre, descripcion, grupo, categoria) VALUES (33, 'Mazamorras', 'Sedimentos arrastrados por una corriente de agua que forma una masa enorme de barro o lodo, arrastrando con ella todo lo que encuentra a us paso.', 'Geológico', 'Movimiento de masas') ON CONFLICT (nombre) DO NOTHING;
INSERT INTO edan.tipo_evento (id_tipo_evento, nombre, descripcion, grupo, categoria) VALUES (34, 'Flujo de lava', 'Es una corriente de roca fundida que se derrama desde el respiradero de un volcán en erupción.', 'Geológico', 'Erupción volcánica') ON CONFLICT (nombre) DO NOTHING;
INSERT INTO edan.tipo_evento (id_tipo_evento, nombre, descripcion, grupo, categoria) VALUES (35, 'Gases volcánicos', 'Fluido sin forma ni volúmen propios, cuyas moléculas tienden a separarse unas de otras y presentan mayor movilidad que la de los líquidos emanados por volcán y constituyen la mayor parte del volmen de las erupciones volcánicas.', 'Geológico', 'Erupción volcánica') ON CONFLICT (nombre) DO NOTHING;
INSERT INTO edan.tipo_evento (id_tipo_evento, nombre, descripcion, grupo, categoria) VALUES (36, 'Caida de cenizas', 'Es una composición de partículas de roca y mineral muy finas (de menos de 2 mm de diámetro) estos son peligrosos y tienen efecto sobre la salud de las personas y animales.', 'Geológico', 'Erupción volcánica') ON CONFLICT (nombre) DO NOTHING;
INSERT INTO edan.tipo_evento (id_tipo_evento, nombre, descripcion, grupo, categoria) VALUES (37, 'Plagas agrícolas', 'Es una población de animales fitófagos (se alimentan de las plantas) que disminuye la producción del cultivo, reduce el valor de la cosecha o incrementa sus costos de producción. Se trata de un criterio esencialmente económico.', 'Biológico', 'Plagas') ON CONFLICT (nombre) DO NOTHING;
INSERT INTO edan.tipo_evento (id_tipo_evento, nombre, descripcion, grupo, categoria) VALUES (38, 'Plagas de afectación humana', 'Aquellas especies implicadas en la transferencia de enfermedades infeccionasa para el hombre y en el daño o deterioro del hábitad y del bienestar urbano, cuando su existencia es continua en el tiempo y está por encima del umbral de tolerancia.', 'Biológico', 'Plagas') ON CONFLICT (nombre) DO NOTHING;
INSERT INTO edan.tipo_evento (id_tipo_evento, nombre, descripcion, grupo, categoria) VALUES (39, 'Contaminación del aire', 'Alteración nociva de la pureza de las condiciones normales del aire por un medio químico o físico (gases, partículas u otros elementos extraños).', 'Antrópico y tecnológico', 'Contaminación') ON CONFLICT (nombre) DO NOTHING;
INSERT INTO edan.tipo_evento (id_tipo_evento, nombre, descripcion, grupo, categoria) VALUES (40, 'Contaminación del agua', 'Consiste en una modificación, generalmente provocada por el hombre, de la calidad del agua, haciéndola impropia o peligrosa para el consumo humano, la industría, la agricultrua, la ganderia, la pesca y las actividades recreativas, así como para los animales domésticos y la vida natural.', 'Antrópico y tecnológico', 'Contaminación') ON CONFLICT (nombre) DO NOTHING;
INSERT INTO edan.tipo_evento (id_tipo_evento, nombre, descripcion, grupo, categoria) VALUES (41, 'Contaminación del suelo', 'Supone la alteración de la superficie terrestre con sustancias químicas que resultan perjudiciales para la vida en distntas medida, poniendo en peligro los ecosistema y la salud , también puede afectar gravemente a la flora y la fauna o corto, mediano y largo plazo.', 'Antrópico y tecnológico', 'Contaminación') ON CONFLICT (nombre) DO NOTHING;
INSERT INTO edan.tipo_evento (id_tipo_evento, nombre, descripcion, grupo, categoria) VALUES (42, 'Erosión', 'Es un proceso provocado por la acción del viento, agua o las actividades humanas, tiende a modificar el relieve estructural del suelo, además de la pérdida de la capa vegetal que cubre la tierra, dejándola sin capacidad productiva.', 'Antrópico y tecnológico', 'Degradación') ON CONFLICT (nombre) DO NOTHING;
INSERT INTO edan.tipo_evento (id_tipo_evento, nombre, descripcion, grupo, categoria) VALUES (43, 'Desertificación', 'Es la degradación de una o varias zonas ecológicas, como consecuencia de las variaciones climáticas o la acción humana, debido a las talas, quemas para la agricultura, minería, ganadería u otros.', 'Antrópico y tecnológico', 'Degradación') ON CONFLICT (nombre) DO NOTHING;
INSERT INTO edan.tipo_evento (id_tipo_evento, nombre, descripcion, grupo, categoria) VALUES (44, 'Deforestación', 'Proceso de despojar árboles y plantas de una  superficie boscosa, provocado generalmente por la acción humana, debido a las talas, quemas para agricultura, minería, ganadería u otros.', 'Antrópico y tecnológico', 'Degradación') ON CONFLICT (nombre) DO NOTHING;
INSERT INTO edan.tipo_evento (id_tipo_evento, nombre, descripcion, grupo, categoria) VALUES (45, 'Incendios industriales', 'Son incendios no controlados de grandes proporciones, que pueden presentarse e forma súbita, gradual e instantánea en plantas industriales que emplean agentes químicos y en el tránsito de vehículos con tanques, líquidos inflamables y/o tóxicos, la generada por cableado eléctrico de alta tensión, en bodegas de material combustible espontáneo.', 'Antrópico y tecnológico', 'Incendios') ON CONFLICT (nombre) DO NOTHING;
INSERT INTO edan.tipo_evento (id_tipo_evento, nombre, descripcion, grupo, categoria) VALUES (46, 'Incendios estructurales', 'Es aquel tipo de incendio  que se produce en casas, edificios, locales comerciales, etc. Provocado por negligencia humana, terrorismo o conflicto social.', 'Antrópico y tecnológico', 'Incendios') ON CONFLICT (nombre) DO NOTHING;
INSERT INTO edan.tipo_evento (id_tipo_evento, nombre, descripcion, grupo, categoria) VALUES (47, 'Escasez de combustible', 'La escasez de combustibles en un territorio o país representa un riesgo que limita el tránsito y el transporte normal. Esta situación afecta directamente la economía, ya que interrumpe el flujo de personas, bienes y servicios, generando pérdidas productivas y encarecimiento de costos logísticos.', 'Antrópico y tecnológico', 'Escasez de combustible') ON CONFLICT (nombre) DO NOTHING;
INSERT INTO edan.tipo_evento (id_tipo_evento, nombre, descripcion, grupo, categoria) VALUES (48, 'Otro', NULL, 'Otro', 'Otro') ON CONFLICT (nombre) DO NOTHING;

-- Ajuste de la secuencia al máximo id insertado/catalogado
SELECT setval(pg_get_serial_sequence('edan.tipo_evento', 'id_tipo_evento'), (SELECT COALESCE(MAX(id_tipo_evento), 1) FROM edan.tipo_evento), true);

COMMIT;

SELECT 'IDEMPOTENT OK v2.13.0' AS resultado;
